  <div class="brain-info" id="brainInfo">
    <div class="brain-info-title" id="brainTitle">Tap a part of the brain</div>
    <div id="brainText">Each region has its own job. Click one to find out what it does.</div>
  </div>
</div>

<script>
(function () {
  const info = {
    frontal: { name: "Frontal Lobe", text: "Handles decision making, planning, personality and emotional control. It keeps developing until around age 25." },
    motor: { name: "Motor Cortex", text: "Sends the signals that move your muscles. It sits at the back of the frontal lobe, just in front of the sensory strip." },
    sensory: { name: "Sensory Cortex", text: "Receives touch, pressure, pain and temperature from the body, and tells you where each sensation came from." },
    parietal: { name: "Parietal Lobe", text: "Processes spatial awareness and body position, and combines the senses. It helps you know where your hand is without looking." },
    temporal: { name: "Temporal Lobe", text: "Handles hearing, language and memory. The hippocampus, key to forming memories, is tucked inside it." },
    occipital: { name: "Occipital Lobe", text: "Processes everything you see. It sits at the back of the head, far from the eyes." },
    cerebellum: { name: "Cerebellum", text: "Coordinates balance, movement and motor learning. It holds about 80 percent of the brain's neurons." },
    brainstem: { name: "Brainstem", text: "Controls breathing, heartbeat and sleep. It connects the brain to the spinal cord." }
  };

  const wrap = document.getElementById('brainWrap');
  const svg = document.getElementById('brainSvg');
  const title = document.getElementById('brainTitle');
  const text = document.getElementById('brainText');
  const lobes = svg.querySelectorAll('.lobe');

  function burst(e) {
    const r = wrap.getBoundingClientRect();
    const x = e.clientX - r.left;
    const y = e.clientY - r.top;
    for (let i = 0; i < 8; i++) {
      const dot = document.createElement('span');
      const angle = (Math.PI * 2 * i) / 8;
      dot.className = 'burst';
      dot.style.left = x + 'px';
      dot.style.top = y + 'px';
      dot.style.setProperty('--dx', Math.cos(angle) * 44 + 'px');
      dot.style.setProperty('--dy', Math.sin(angle) * 44 + 'px');
      wrap.appendChild(dot);
      setTimeout(function () { dot.remove(); }, 700);
    }
  }

  lobes.forEach(function (lobe) {
    lobe.addEventListener('click', function (e) {
      const data = info[lobe.dataset.lobe];
      title.textContent = data.name;
      text.textContent = data.text;
      lobes.forEach(function (l) { l.classList.remove('active'); });
      lobe.classList.add('active');
      burst(e);
    });
  });

  wrap.addEventListener('mousemove', function (e) {
    const r = wrap.getBoundingClientRect();
    const x = (e.clientX - r.left) / r.width - 0.5;
    const y = (e.clientY - r.top) / r.height - 0.5;
    svg.style.transform = 'perspective(700px) rotateY(' + (x * 14) + 'deg) rotateX(' + (-y * 10) + 'deg)';
  });

  wrap.addEventListener('mouseleave', function () {
    svg.style.transform = '';
  });
})();
</script>